const r = require\('./data/replays/20260311-231034-641240.json'\);
const defs = r.unitDefs;
const shermanIndices = defs.map\(\(d,i\) => d.unitId === 'sherman' ? i : -1\).filter\(i => i >= 0\);
console.log\('Sherman indices:', shermanIndices.map\(i => defs[i].id + ' \(idx ' + i + '\)'\)\);

// Sample every 10 frames \(~1 second at 10fps\)
const fps = r.frames.length / r.duration;
console.log\('Effective FPS:', fps.toFixed\(1\)\);
const step = Math.round\(fps\); // ~1 second

