  const id = defs[si].id;
  console.log\('\\n--- ' + id + ' ---'\);
  let switches = 0, prevTgt = null, tgtDurations = {};
  let lastSwitchFrame = 0;

  for \(let f = 0; f < r.frames.length; f += step\) {
    const frame = r.frames[f];
    const u = frame.units[si];
    if \(u.dead\) { console.log\('t=' + frame.t.toFixed\(1\) + ' DEAD'\); break; }
    const tgt = u.tgt || '\(none\)';
    const timeSec = frame.t.toFixed\(1\);

