      } else {
        console.log\('t=' + timeSec + ' tgt=' + tgt\);
      }
      lastSwitchFrame = f;
      prevTgt = tgt;
    }

    tgtDurations[tgt] = \(tgtDurations[tgt] || 0\) + \(r.duration / r.frames.length\);
