// units array = blue team \(indices 0-5\), enemies = red team \(indices 0-5\)
// blue: hero\(0\), b.inf.0\(1\), b.inf.1\(2\), b.inf.2\(3\), b.inf.3\(4\), b.shm.0\(5\), b.shm.1\(6\)
