console.log\('Hero present:', !!f0.hero\);

// So units[0..5] = b.inf.0, b.inf.1, b.inf.2, b.inf.3, b.shm.0, b.shm.1
// enemies[0..5] = r.inf.0, r.inf.1, r.inf.2, r.inf.3, r.shm.0, r.shm.1

// Sherman indices: units[4]=b.shm.0, units[5]=b.shm.1, enemies[4]=r.shm.0, enemies[5]=r.shm.1
const shermanFrameMap = {
  'b.shm.0': {arr: 'units', idx: 4},
  'b.shm.1': {arr: 'units', idx: 5},
  'r.shm.0': {arr: 'enemies', idx: 4},
  'r.shm.1': {arr: 'enemies', idx: 5},
};

// Sample every ~10 frames \(roughly 1s at 10fps\)
for \(const [id, loc] of Object.entries\(shermanFrameMap\)\) {
  const targets = [];
  let switches = 0;
  let lastTarget = null;
  for \(let i = 0; i < r.frames.length; i += 10\) {
    const f = r.frames[i];
    const u = f[loc.arr][loc.idx];
    if \(u && !u.dead && u.tgt\) {
      if \(lastTarget && u.tgt !== lastTarget\) switches++;
      lastTarget = u.tgt;
      targets.push\({t: f.t, tgt: u.tgt}\);
    }
  }
  console.log\(id + ': switches=' + switches + ' samples=' + targets.length\);
  // Show target sequence
  let seq = [];
  let prev = '';
  targets.forEach\(t => {
    if \(t.tgt !== prev\) { seq.push\(t.tgt + '@' + \(t.t/1000\).toFixed\(0\) + 's'\); prev = t.tgt; }
  }\);
  console.log\('  Sequence:', seq.join\(' -> '\)\);
}
