for \(let i = 0; i < r.frames.length; i++\) {
  const f = r.frames[i];
  const t = f.t / 1000;
  [...f.units, ...f.enemies].forEach\(\(u, idx\) => {
    if \(!u || u.dead\) return;
    const key = idx < f.units.length ? 'blue_'+idx : 'red_'+\(idx-f.units.length\);
    if \(u.st === 'hull_down' && \(!u.tgt || u.tgt === 'NONE'\)\) {
      if \(!hullDownNoTarget[key]\) hullDownNoTarget[key] = { start: t, dur: 0 };
      hullDownNoTarget[key].dur = t - hullDownNoTarget[key].start;
    } else {
      if \(hullDownNoTarget[key] && hullDownNoTarget[key].dur > 3\) {
        console.log\('IDLE hull_down:', key, 'duration:', hullDownNoTarget[key].dur.toFixed\(1\)+'s', 'at t='+hullDownNoTarget[key].start.toFixed\(1\)\);
      }
      delete hullDownNoTarget[key];
    }
  }\);
}
// Check remaining
for \(const [key, v] of Object.entries\(hullDownNoTarget\)\) {
  if \(v.dur > 3\) console.log\('IDLE hull_down:', key, 'duration:', v.dur.toFixed\(1\)+'s', 'at t='+v.start.toFixed\(1\)\);
}
// Check if base factor appears in fire events
const fireEvents = r.events.filter\(e => e.type === 'fire'\);
const hasBase = fireEvents.some\(e => e.detail && e.detail.includes\('base:'\)\);
console.log\('baseAccuracy in fire events:', hasBase\);
// Accuracy distribution
const accs = fireEvents.map\(e => parseFloat\(e.acc\)\).filter\(a => !isNaN\(a\)\);
